import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.hwbV7reR.js";const u=JSON.parse('{"title":"Сообщение об уязвимости","description":"","frontmatter":{},"headers":[],"relativePath":"security.md","filePath":"security.md","lastUpdated":1791695486000}'),i={name:"security.md"};function o(n,t,s,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="сообщение-об-уязвимости" tabindex="-1">Сообщение об уязвимости <a class="header-anchor" href="#сообщение-об-уязвимости" aria-label="Permalink to &quot;Сообщение об уязвимости&quot;">​</a></h1><p>Не публикуйте ключи, токены, конфигурации туннеля или данные пользователей в Issues, Pull Requests и примерах воспроизведения.</p><p>Если на странице GitHub Security этого репозитория доступна кнопка <strong>Report a vulnerability</strong>, используйте её. Включение private vulnerability reporting ещё нужно проверить перед публичным выпуском; наличие этого документа не включает функцию GitHub. Если кнопки нет, создайте Issue только с просьбой предоставить приватный канал, без описания эксплуатации и чувствительных данных.</p><p>Для приватного сообщения подготовьте версию/commit, затронутый компонент, ожидаемое и фактическое поведение, минимальный пример с синтетическими данными. У проекта пока нет обещанного SLA обработки и политики поддержки старых веток.</p><h2 id="границы-доверия" tabindex="-1">Границы доверия <a class="header-anchor" href="#границы-доверия" aria-label="Permalink to &quot;Границы доверия&quot;">​</a></h2><p>API вызывается доверенным backend по служебному Bearer-токену. Backend проверяет пользователя и право на действие. Это не многоарендная граница между недоверенными backend: токен даёт полномочия управления техническими назначениями.</p><p>У каждого узла отдельный токен и проверяемая server identity. HTTP-ответы с конфигурациями секретны. SSH для установки узла не должен превращаться в runtime зависимость выдачи подключения. Вопросы безопасной эксплуатации описаны в <a href="./operations.html">операциях</a> и <a href="./node-agent.html">контракте агента</a>.</p><h2 id="классификация-данных" tabindex="-1">Классификация данных <a class="header-anchor" href="#классификация-данных" aria-label="Permalink to &quot;Классификация данных&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Данные</th><th>Допустимое использование</th></tr></thead><tbody><tr><td>Backend-токен и токены агентов</td><td>Приватные файлы, память процесса, защищённый Authorization-заголовок; не Git, URL, журналы или ответы API</td></tr><tr><td>Приватные VPN-ключи, документы конфигурации, содержимое QR</td><td>Память при выдаче авторизованному получателю; не центральная SQLite, диагностика или логи</td></tr><tr><td>Идентификаторы устройства, подключения и операции</td><td>Журнал технического состояния; ограниченный операторский доступ, без публичных списков</td></tr><tr><td>IP/адреса API узлов, состояние, сроки доступа</td><td>Настройки и техническое состояние; не общедоступная диагностика</td></tr><tr><td>Пароли пользователя, оплата и свободные слоты</td><td>Система заказчика; оркестратору не передаются</td></tr></tbody></table><p>Ответы с параметрами имеют no-store. Это не предотвращает запись внешним reverse proxy: его конфигурация также должна исключать тела и Authorization. Новые логи формируются по разрешённому набору полей; произвольный текст upstream-ошибки или repr объекта нельзя включать в событие. Структурированные события и метрики описаны в <a href="./observability.html">диагностике</a>. Их проверки покрывают секреты в исключениях, заголовках, URL и выдаваемых документах.</p><h2 id="управление-и-панель-просмотра" tabindex="-1">Управление и панель просмотра <a class="header-anchor" href="#управление-и-панель-просмотра" aria-label="Permalink to &quot;Управление и панель просмотра&quot;">​</a></h2><p>Изменения выполняет локальный CLI или панель с явно включённым <code>--manage</code>, с правами сервисного пользователя. Backend доверен для технических назначений, но не управляет серверным реестром через HTTP. <a href="./panel.html">Панель</a> работает отдельно на loopback, со своим ключом: совпадение с backend-ключом блокирует запуск. Прежний <code>admin_token_file</code> не используется.</p><p>Сессия хранится в памяти процесса один час; cookie HttpOnly/SameSite=Strict. Проверяются Host, Origin для POST и Sec-Fetch-Site. Ответы запрещают кэширование, встраивание во фреймы и внешние ресурсы через CSP. Ключи не сохраняются в браузерном хранилище. Удалённый доступ — через SSH forwarding, без публикации порта. В режиме просмотра нет мутаций. Режим управления принимает URL и ключ агента только на входе; они не попадают в аудит и ответы. VPN-документы не выдаются. Это административные данные, поэтому их нельзя считать публичными. Ключ панели с <code>--manage</code> имеет полномочия оператора. Персональных ролей пока нет; метка cli/panel в аудите показывает канал команды, а не личность пользователя. <a href="./release-security.html">Проверки выпуска</a> включают автономный поиск секретов и проверку зависимостей по публичной базе уязвимостей.</p>',13)])])}const m=e(i,[["render",o]]);export{u as __pageData,m as default};
